output_text:
[
  {
    "id": "no_carts_in_facing_shelf_aisles",
    "text": "Shopping carts are prohibited in single-file aisles between facing shelves.",
    "abstraction": {
      "state_properties": {
        "facingShelfAisle": {
          "and": [
            "shelfE",
            "shelfW",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "facingShelfAisle"
        ]
      }
    }
  },
  {
    "id": "do_not_enter_single_file_with_cart",
    "text": "A customer must not push a cart into a single-file shelf aisle.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            "adjShelf",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        }
      },
      "events": {
        "moveIntoSingleFileWithCart": {
          "pre": {
            "and": [
              "hasCart",
              {
                "or": [
                  "N",
                  "S",
                  "E",
                  "W"
                ]
              }
            ]
          },
          "post": "singleFileShelfAisle"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "moveIntoSingleFileWithCart"
    }
  },
  {
    "id": "park_cart_only_at_aisle_mouth",
    "text": "Carts may only be parked or released at designated wide aisle mouths, not arbitrarily in the store.",
    "abstraction": {
      "state_properties": {
        "cartParkingMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        },
        "cartBay": {
          "or": [
            "at(0,7)",
            "at(1,7)"
          ]
        },
        "approvedCartReleasePlace": {
          "or": [
            "cartParkingMouth",
            "cartBay"
          ]
        }
      },
      "events": {
        "releaseCart": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "releaseCart",
          {
            "not": "approvedCartReleasePlace"
          }
        ]
      }
    }
  },
  {
    "id": "reclaim_cart_after_customer_aisle",
    "text": "After returning from a customer-only single-file aisle, the customer is obliged to reclaim the parked cart before continuing.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            "adjShelf",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        },
        "cartParkingMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        }
      },
      "events": {
        "returnToCartMouthWithoutCart": {
          "pre": {
            "and": [
              "singleFileShelfAisle",
              {
                "not": "hasCart"
              },
              {
                "or": [
                  "S",
                  "N",
                  "E",
                  "W"
                ]
              }
            ]
          },
          "post": "cartParkingMouth"
        },
        "pickUpParkedCart": {
          "pre": {
            "and": [
              "cartParkingMouth",
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "returnToCartMouthWithoutCart",
      "discharge": "pickUpParkedCart"
    }
  },
  {
    "id": "cartless_only_in_customer_aisle_or_cart_zone",
    "text": "Customers should not be without their cart except at the entrance/cart bay, at a cart-parking mouth, or inside a customer-only shelf aisle.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            "adjShelf",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        },
        "cartParkingMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        },
        "entranceCartZone": {
          "or": [
            "at(0,7)",
            "at(1,7)"
          ]
        },
        "allowedCartlessZone": {
          "or": [
            "singleFileShelfAisle",
            "cartParkingMouth",
            "entranceCartZone"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          {
            "not": "hasCart"
          },
          {
            "not": "allowedCartlessZone"
          }
        ]
      }
    }
  },
  {
    "id": "cart_required_for_accessible_shelf_service",
    "text": "When interacting with a shelf from a cart-accessible aisle, the customer must have a cart.",
    "abstraction": {
      "state_properties": {
        "cartAccessibleShelfFace": {
          "and": [
            "adjShelf",
            {
              "gt": [
                "freeWidthH",
                1
              ]
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "INTERACT",
          "cartAccessibleShelfFace",
          {
            "not": "hasCart"
          }
        ]
      }
    }
  },
  {
    "id": "cartless_service_in_facing_shelf_aisle",
    "text": "Items located in facing-shelf single-file aisles must be handled without a cart.",
    "abstraction": {
      "state_properties": {
        "facingShelfAisle": {
          "and": [
            "shelfE",
            "shelfW",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "INTERACT",
          "facingShelfAisle",
          "hasCart"
        ]
      }
    }
  },
  {
    "id": "one_way_cart_flow_in_broad_aisles",
    "text": "In broad cart aisles, carts must follow the one-way circulation and may not be pushed west.",
    "abstraction": {
      "state_properties": {
        "broadCartAisle": {
          "gt": [
            "freeWidthH",
            1
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "broadCartAisle",
          "W"
        ]
      }
    }
  }
]
